// View chips for the vessel on stage, and "compare": the current view's
// reference photograph beside the render, with its credit line. Reference
// photos are not in the main bundle; refs.js (generated by tools/refs.mjs)
// lists exactly the photographs a view names, each a lazily resolved URL.

import { el } from './ui.js'
import { refLoader, refCredit } from './refs.js'

/** A close-up: a named detail, or a view framing a small part of the vessel. */
export const isDetailView = (name, v) => /^detail/.test(name) || (v?.fit ?? 1) < 0.6
const pretty = (name) => name.replace(/^detail-/, '').replace(/-/g, ' ')

export function createViewBar({ chipsEl, detailEl, detailToggle, compareToggle, figure, onView, onLayout }) {
  let artifact = null
  let view = null
  let detailsOpen = false
  let compareOn = false
  let loadToken = 0
  const img = figure.querySelector('img')
  const caption = figure.querySelector('figcaption')

  function chip(name, v) {
    return el('button', {
      type: 'button',
      class: 'view' + (v.ref ? ' has-ref' : ''),
      'data-view': name,
      'aria-pressed': String(name === view),
      title: v.ref ? 'Has a reference photograph' : null,
      text: pretty(name),
      onclick: () => onView(name),
    })
  }

  function render() {
    const vs = Object.entries(artifact?.views || {})
    const main = vs.filter(([n, v]) => !isDetailView(n, v))
    const det = vs.filter(([n, v]) => isDetailView(n, v))
    chipsEl.replaceChildren(...main.map(([n, v]) => chip(n, v)))
    detailEl.replaceChildren(...det.map(([n, v]) => chip(n, v)))
    // a detail view that is current keeps the details row open
    if (det.some(([n]) => n === view)) detailsOpen = true
    detailToggle.hidden = !det.length
    detailToggle.querySelector('.n').textContent = det.length ? String(det.length) : ''
    applyDetails()
    syncCompare()
  }

  function applyDetails() {
    detailEl.hidden = !detailsOpen || !detailEl.childElementCount
    detailToggle.setAttribute('aria-expanded', String(detailsOpen && !detailEl.hidden))
  }

  detailToggle.addEventListener('click', () => {
    detailsOpen = !detailsOpen
    applyDetails()
    onLayout()
  })
  compareToggle.addEventListener('click', () => {
    if (compareToggle.getAttribute('aria-disabled') === 'true') return
    compareOn = !compareOn
    syncCompare()
    onLayout()
  })

  function currentRef() {
    return artifact?.views?.[view]?.ref || null
  }

  function syncCompare() {
    const ref = currentRef()
    const loader = ref ? refLoader(artifact.id, ref) : null
    compareToggle.setAttribute('aria-disabled', String(!loader))
    compareToggle.setAttribute('aria-pressed', String(compareOn && !!loader))
    compareToggle.title = loader ? 'Show the reference photograph beside the render' : 'No reference photograph for this view'
    const show = compareOn && !!loader
    figure.hidden = !show
    document.documentElement.classList.toggle('comparing', show)
    if (!show) return
    const my = ++loadToken
    figure.classList.add('loading')
    caption.replaceChildren(el('span', { class: 'cap', text: 'Reference photograph · ' + pretty(view) }), el('span', { class: 'credit', text: refCredit(artifact.id, ref) }))
    loader().then((url) => {
      if (my !== loadToken) return
      img.onload = () => my === loadToken && figure.classList.remove('loading')
      img.onerror = () => {
        if (my !== loadToken) return
        figure.classList.remove('loading')
        caption.prepend(el('span', { class: 'fine', text: 'The photograph could not be loaded.' }))
      }
      img.alt = `Reference photograph: ${artifact.title}, ${pretty(view)}`
      img.src = url
    })
  }

  return {
    setArtifact(a, v) {
      artifact = a
      view = v
      detailsOpen = false
      render()
    },
    setView(v) {
      view = v
      for (const b of [...chipsEl.children, ...detailEl.children]) b.setAttribute('aria-pressed', String(b.dataset.view === v))
      if (isDetailView(v, artifact?.views?.[v]) && !detailsOpen) {
        detailsOpen = true
        applyDetails()
      }
      syncCompare()
    },
    get comparing() {
      return compareOn && !figure.hidden
    },
    setCompare(on) {
      compareOn = !!on
      syncCompare()
    },
  }
}
